Province: ${province}
Tax Rate: ${result.taxRate}%
Pre-Tax Amount: ${fmtCurrency(result.preTaxAmount)}
Tax Amount: ${fmtCurrency(result.taxAmount)}
Total Amount: ${fmtCurrency(result.totalAmount)}
`.trim();

